// Root entrypoint for the OpenCode 2 directory-form plugin loader.
// The loader imports `index.js` from the plugin root and ignores package.json
// "main"/"exports", so this shim must exist and re-export the default plugin.
export { default } from "./src/index.js"

#!/usr/bin/env node
import { createMemoryReads, credentialToken } from "./index.mjs"
import { safeError } from "./registry.mjs"
import { serveStdio } from "./stdio.mjs"
import { createMemoryHttpServer } from "./http.mjs"

try {
  const [command, json = "{}", space, ...rest] = process.argv.slice(2)
  const sdk = createMemoryReads({ origin: process.env.MEMORY_ORIGIN })
  if (command === "mcp-http" && process.argv.length === 3) {
    // MEMORY_TOKEN is deliberately not read in this mode.
    const port = Number(process.env.MEMORY_PORT ?? 8422)
    if (!Number.isInteger(port) || port < 0 || port > 65535) throw new Error("invalid port")
    const server = createMemoryHttpServer({ sdk, gatewayAuthorize: sdk.gatewayAuthorize, allowedOrigins: process.env.MEMORY_ALLOWED_ORIGINS ? JSON.parse(process.env.MEMORY_ALLOWED_ORIGINS) : [] })
    server.server.on("error", () => { process.stderr.write('{"error":"listener_unavailable"}\n'); process.exitCode = 1 })
    server.server.once("listening", () => process.stderr.write(`${JSON.stringify({ listening: `http://127.0.0.1:${server.server.address().port}` })}\n`))
    server.listen(port)
    const stop = () => { void server.close().then(() => process.exit(0)) }
    process.once("SIGTERM", stop)
    process.once("SIGINT", stop)
  } else if (command === "mcp-stdio" && process.argv.length === 3) {
    const token = credentialToken(process.env.MEMORY_TOKEN)
    serveStdio({ sdk, token, onClose: () => process.stdout.end(() => process.exit(0)) })
  } else {
    if (rest.length || !["records.get", "records.list"].includes(command)) throw new Error("usage")
    const token = credentialToken(process.env.MEMORY_TOKEN)
    const input = JSON.parse(json)
    const result = await sdk.records[command.slice(8)](input, { token, ...(space ? { space } : {}) })
    process.stdout.write(`${JSON.stringify(result)}\n`)
  }
} catch (error) {
  process.stderr.write(`${JSON.stringify({ error: safeError(error) })}\n`)
  process.exitCode = 1
}

import { createRecordsClient } from "../src/backend/records.js"
import { LIMITS, ReadError, object, safeError, validateRead } from "./registry.mjs"
export { ReadError, readRegistry } from "./registry.mjs"

export function trustedOrigin(value) {
  let url
  try { url = new URL(value) } catch { throw new ReadError("invalid_origin") }
  if (url.username || url.password || url.pathname !== "/" || url.search || url.hash || !["https:", "http:"].includes(url.protocol) || (url.protocol !== "https:" && !["127.0.0.1", "[::1]", "localhost"].includes(url.hostname))) throw new ReadError("invalid_origin")
  return url.origin
}
export function credentialToken(value) {
  if (typeof value !== "string" || !value || value.length > 8192 || /[^\x21-\x7e]/.test(value)) throw new ReadError("unauthorized", 401)
  return value
}

// Redirects are disabled, including same-origin redirects. Consume bounded
// bodies inside the deadline, before the existing client parses the response.
async function boundedFetch(url, init, signal, fetchImpl) {
  const response = await fetchImpl(url, { ...init, redirect: "manual", signal: AbortSignal.any([signal, ...(init.signal ? [init.signal] : [])]) })
  if (response.status >= 300 && response.status < 400) {
    await response.body?.cancel()
    throw new ReadError("redirect_refused", 502)
  }
  const chunks = []
  let size = 0
  for await (const chunk of response.body ?? []) {
    size += chunk.length
    if (size > LIMITS.outputBytes) throw new ReadError("response_too_large", 502)
    chunks.push(chunk)
  }
  return new Response(Buffer.concat(chunks), { status: response.status, headers: response.headers })
}

/** A two-method HTTP JSON SDK; no OpenCode context or cell credentials.
 * @param {{origin: string, credential?: () => string | Promise<string>, fetchImpl?: typeof fetch, deadlineMs?: number}} config
 */
export function createMemoryReads({ origin, credential, fetchImpl = fetch, deadlineMs = LIMITS.deadlineMs }) {
  const audience = trustedOrigin(origin)
  if (!Number.isInteger(deadlineMs) || deadlineMs < 1 || deadlineMs > LIMITS.deadlineMs) throw new ReadError("invalid_request")
  async function context(options = {}) {
    const token = credentialToken(options.token ?? await credential?.())
    if (options.space !== undefined && (typeof options.space !== "string" || !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(options.space))) throw new ReadError("invalid_space")
    return { token, signal: AbortSignal.any([AbortSignal.timeout(deadlineMs), ...(options.signal ? [options.signal] : [])]), space: options.space }
  }
  async function read(name, input, options) {
    let ctx
    try {
      validateRead(name, input)
      ctx = await context(options)
      const client = createRecordsClient({ controlURL: audience, timeoutMs: deadlineMs, retries: 0, timeZone: "UTC" }, {
        credentials: { bearer: async () => ctx.token, refresh: async () => "" },
        fetchImpl: (url, init) => boundedFetch(url, init, ctx.signal, fetchImpl),
      })
      return await client.call(name, input, { space: ctx.space, retries: 0 })
    } catch (error) {
      if (ctx?.signal.aborted) throw new ReadError(ctx.signal.reason?.name === "TimeoutError" ? "timeout" : "cancelled", ctx.signal.reason?.name === "TimeoutError" ? 408 : 499)
      throw safeError(error)
    }
  }
  // Verification uses the existing PUBLIC context route, never internal
  // control credentials, guessed roles, or a nonempty-bearer boolean.
  async function gatewayAuthorize(options) {
    try {
      const ctx = await context(options)
      const response = await boundedFetch(`${audience}/v1/context`, { method: "POST", headers: { authorization: `Bearer ${ctx.token}`, "content-type": "application/json" }, body: JSON.stringify(ctx.space ? { space_id: ctx.space } : {}) }, ctx.signal, fetchImpl)
      if (!response.ok) throw new ReadError(response.status === 401 ? "unauthorized" : response.status === 403 ? "forbidden" : "upstream_unavailable", response.status)
      const data = await response.json()
      if (!object(data) || data.routing !== "gateway" || typeof data.user?.id !== "string" || !data.user.id) throw new ReadError("invalid_gateway_context", 502)
      return Object.freeze({ principal: data.user.id })
    } catch (error) { throw safeError(error) }
  }
  return Object.freeze({ records: Object.freeze({ get: (input, options) => read("records.get", input, options), list: (input = {}, options) => read("records.list", input, options) }), gatewayAuthorize })
}

import { applySkipAsksSource, configWarnings, resolveConfig } from "./config.js"
import { asSession, createCredentials, followOrigin, memoryResourceAvailable, memoryResourceOrigin, SOURCES } from "./credentials.js"
import { createConnectSource, gatewayOrigin, registerConnect } from "./connect.js"
import { createLogger } from "./log.js"
import { createBackend } from "./backend/v3.js"
import { createRuntime } from "./runtime.js"
import { registerTools } from "./tools/index.js"
import {
  registerMirroredSkills,
  registerBuiltinSkill,
  syncSkills,
  SKILL_REFRESH_BACKGROUND_MS,
  SKILL_RETRY_DELAYS_MS,
  SKILL_REFRESH_START_MS,
} from "./skills.js"
import { registerCommands } from "./commands.js"
import { attachMemoryHooks } from "./hooks.js"
import { attachCapture } from "./events.js"
import { registerViewRpc } from "./views/rpc.js"
import { registerSourceRpc } from "./sources/rpc.js"
import { registerDefaultRules } from "./permissions.js"
import { createSetupTimer } from "./setup-time.js"
import { hostRefusal, registerRefusal } from "./host-refusal.js"
import { errorMessage } from "./util.js"

/**
 * OpenCode 2 plugin entrypoint.
 *
 * Design constraints that shaped this file:
 * - zero runtime imports, because the host does not resolve npm packages for
 *   directory plugins;
 * - setup never throws, because one bad backend must not stop the session;
 * - the host must be OpenCode 2.1.4 or newer; older hosts are refused;
 * - with no credential for a gateway (or inside Jelly) it still loads and
 *   registers its tools, but captures nothing, spools nothing, and every tool
 *   says why memory is unavailable (`src/credentials.js`).
 */
export default {
  id: "mem",

  async setup(ctx) {
    // One timer per engine start, on a monotonic clock: the phases are what
    // `memory.setup` answers, and what the host's engine-start telemetry names
    // (jelly #80, src/setup-time.js). Marks are cheap; nothing is read from it.
    const setupTime = createSetupTimer()
    let config
    try {
      // Jelly's sheet shows `ownService` as it will be applied, so the switch is
      // resolved with whether this host is Jelly's at all: the accessors it
      // publishes are the only signal there is.
      config = resolveConfig({ ...(ctx?.options ?? {}), memoryResourceOffered: memoryResourceAvailable() })
    } catch (error) {
      console.error(`[mem] invalid configuration: ${errorMessage(error)}`)
      return
    }
    setupTime.mark("config")

    const log = createLogger(config)
    const version = String(ctx?.app?.version ?? "")
    const refusal = hostRefusal(version)
    if (refusal) {
      // OpenCode discards a plugin's console output, so the reason has to be
      // reachable without it: one tool that says it (the agent can tell the
      // person, and anyone can call it), and Memory's own debug log. Nothing
      // else is registered — no hooks, no protocol block, no request — and the
      // console line stays for a host or a run that does show it.
      console.error(`[mem] ${refusal.sentence}`)
      log.error(refusal.sentence)
      // Deliberately not caught: if the one tool cannot be registered, the
      // failure belongs in the host's own log rather than in silence.
      await registerRefusal(ctx, refusal.sentence)
      return
    }
    const missing = [
      ["tool.transform", ctx?.tool?.transform],
      ["skill.transform", ctx?.skill?.transform],
      ["command.transform", ctx?.command?.transform],
      ["session.hook", ctx?.session?.hook],
      ["event.subscribe", ctx?.event?.subscribe],
      ["permission.assert", ctx?.permission?.assert],
    ]
      .filter(([, value]) => typeof value !== "function")
      .map(([name]) => name)
    if (missing.length > 0) {
      console.error(`[mem] OpenCode 2.1.4 or newer is required; missing ${missing.join(", ")}`)
      return
    }
    setupTime.mark("host")

    // Credentials and, inside Jelly, the gateway origin are read on use: the
    // accessors Jelly's core plugin publishes may appear after this setup.
    // With a gateway address, a person can also sign in with OpenCode's
    // /connect (src/connect.js); OpenCode keeps and renews that credential.
    // Memory's origin, as it will be used: an address of one's own with the
    // switch on, else Jelly's `memory` resource, read on every use. With either,
    // Memory is registered in /connect, so the declared `account` sign-in row
    // matches the engine integration even while the switch is off (jelly #72).
    const memoryOrigin = () => gatewayOrigin(config.controlURL) || gatewayOrigin(memoryResourceOrigin())
    /**
     * Whether Memory's `/connect` sign-in can be used at all: with the switch on
     * (an address of one's own, where the Jelly identity is never used), or on a
     * host where Jelly's identity offers no `memory` resource. Where Jelly's
     * identity signs the person in, a stored `/connect` credential is never
     * read, so registering the integration would only offer a button that does
     * nothing (R3-S2).
     */
    const signInUsable = config.ownService === true || !memoryResourceOrigin()
    const signIn = memoryOrigin() && signInUsable ? createConnectSource({ integration: ctx?.integration, origin: memoryOrigin, log }) : null
    const credentials = createCredentials({
      token: config.token,
      keyAllowed: config.keyAllowed !== false,
      // R2-B1: the Jelly identity token is Jelly's own (no `cnf`), so with the
      // switch on it is never used: only the key or `/connect` reaches the
      // person's own address.
      identityAllowed: !(config.memoryResourceOffered === true && config.ownService === true),
      log,
      connect: signIn?.supported ? signIn : null,
    })
    // skipAsks: Jelly's setting inside Jelly, else the user-level config only.
    applySkipAsksSource(config, { memoryResourceOffered: () => Boolean(credentials.memoryResource()) })
    const memoryOffered = !config.controlURL && Boolean(credentials.memoryResource())
    // R2-S1: with the switch on, the origin is the person's own address (or
    // none yet), never the resource's: following it would answer with that
    // address.
    if (memoryOffered && config.ownService !== true) followOrigin(config, () => credentials.origin())
    // The switch's "on with no address" is a configuration answer, not local
    // direct mode: it needs the control client's one sentence.
    const gateway = Boolean(config.controlURL) || memoryOffered || config.ownServiceNote === "incomplete"
    setupTime.mark("credentials")

    const backend = createBackend(config, { log, credentials })
    const runtime = createRuntime({ config, log, backend, credentials, gateway })
    runtime.pruneClaims()
    setupTime.mark("backend")

    // Register Memory in /connect, then learn whether a sign-in is stored.
    let connectRegistration = null
    // A sign-in OpenCode holds on disk, read locally: the start's own answer.
    let storedSignIn = false
    // The background probe, when OpenCode's `/connect` can hold a sign-in.
    let signInWarm = null
    if (signIn) {
      try {
        connectRegistration = await registerConnect(ctx, { origin: memoryOrigin, log })
      } catch (error) {
        log.warn("could not add Memory to /connect; keys still work", errorMessage(error))
      }
      // What OpenCode holds is local; confirming it is not. A stored sign-in due
      // for renewal is renewed by OpenCode inside `resolve`, which is a request
      // (opencode-mem#58), so setup starts the probe and awaits none of it:
      // whatever needs the answer joins it at first use (`probeSignIn`,
      // src/credentials.js), and the spool waits for it before replaying.
      if (signIn.supported && !config.token) {
        storedSignIn = await signIn.stored()
        signInWarm = signIn.warm()
      }
    }
    setupTime.mark("connect")

    // The start's own line and warnings say what the disk holds, not what the
    // probe will find: it has not answered yet, and the tools ask at first use.
    // `source()`'s own order, with `/connect`'s stored sign-in where the probe
    // would put it (after Jelly's identity, before a saved key).
    const diskSource = credentials.source()
    const credentialSource = storedSignIn && (diskSource === "" || diskSource === SOURCES.secret) ? SOURCES.connect : diskSource
    log.info("setup", { version, directory: ctx?.location?.directory, memoryResourceOffered: memoryOffered, credential: credentialSource || "none" })
    for (const warning of configWarnings(config, { credentialSource, gateway })) log.warn(warning)
    const unavailable = runtime.unavailable()
    // Not "unavailable" when OpenCode holds a sign-in it has not confirmed yet:
    // the probe decides, and its answer is in the log either way.
    if (unavailable && !storedSignIn) log.info("memory unavailable at setup; tools stay registered", { reason: unavailable })
    setupTime.mark("status")

    const disposers = []
    if (typeof connectRegistration?.dispose === "function") disposers.push(() => connectRegistration.dispose())
    let skillState = { ok: true, count: 0, ids: [], spaceIds: [], sourceSpaces: 0, registration: null }
    // Setup and a session bind can race. Coalesce them so control is asked once
    // and the last requested refresh always runs after the current one.
    let skillRefreshPromise = null
    let skillRefreshQueued = null
    // Nothing this plugin started may run after it is disposed (nits).
    let disposed = false
    const skillTimers = new Set()
    const scheduleSkillWork = (ms, work) => {
      const timer = setTimeout(() => {
        skillTimers.delete(timer)
        if (!disposed) void work()
      }, ms)
      timer.unref?.()
      skillTimers.add(timer)
      return timer
    }
    const clearSkillWork = () => {
      for (const timer of skillTimers) clearTimeout(timer)
      skillTimers.clear()
    }

    runtime.skills = skillState
    runtime.refreshSkills = (options = {}) => {
      if (skillRefreshPromise) {
        skillRefreshQueued = options
        return skillRefreshPromise
      }
      // The mirror serves every session of the engine: work with no session,
      // never one speaker's (src/credentials.js), also when a session's
