// The records-backed core tools (contract §4.1).
import { registerRecall } from "./recall.js"
import { registerRemember, registerRevise } from "./memory.js"
import { registerPage } from "./page.js"
import { registerCommitments } from "./commitments.js"
export const CORE_TOOLS = Object.freeze([registerRecall, registerRemember, registerRevise, registerPage, registerCommitments])

/**
 * Register the `mem_*` tool family and the `/mem-collect` command.
 *
 * Recall is deliberately a tool rather than an automatic injection: pull-based
 * retrieval is cheaper, attributable, and does not invalidate prompt caches.
 *
 * The tools are registered even when memory is unavailable (a gateway or
 * Jelly install with no credential): each then answers the one sentence
 * `runtime.unavailable()` gives and makes no request. Each call runs as its
 * session (`context.sessionID`, `asSession`): inside Jelly it uses that
 * session's token, and in a session whose speaker has no Jelly account linked
 * on the host it answers one sentence saying so.
 *
 * @param {any} ctx
 * @param {any} runtime
 * @param {{ core?: readonly Function[] }} [options] `core`: the core registrations (tests pass contract stubs)
 */
export async function registerTools(ctx, runtime, { core = CORE_TOOLS } = {}) {
  if (!runtime.config.tools) return null
  const toolkit = createToolkit(ctx, runtime)
  toolkit.collector = createCollectorService({ ctx, runtime, toolkit })
  // Plugin declarations (DESIGN-PLUGIN-MEMORY S1): read-only discovery and a
  // report to the records service. It changes nothing the collector does.
  toolkit.plugins = createPluginDiscovery({ ctx, runtime, toolkit })
  // The job host reports its connectors again too (lane 0190), so a newly added plugin counts within seconds.
  runtime.onPluginsChanged = (type) => {
    toolkit.plugins.changed(type)
    toolkit.jobHost?.pluginsChanged?.(type)
  }
