  // process, beside the connector plugins and their sign-ins. It starts below
  // with the collector's timer, behind the same switch: `collect: false` is a
  // host that claims nothing.
  toolkit.jobHost = createJobHost({ ctx, runtime, toolkit })
  // Health and the tests read it here, as they read the collector.
  runtime.jobHost = toolkit.jobHost
  const tools = await ctx.tool.transform((editor) => {
    editor.namespace({ name: "mem", description: MEM_NAMESPACE_DESCRIPTION })
    buildToolset(gateEditor(editor, runtime), toolkit, core)
  })
  let command = null
  try {
    command = await registerCollectCommand(ctx, runtime, toolkit, { asSession })
  } catch (error) {
    runtime.log?.warn?.("the /mem-collect command could not be registered", error)
  }
  // The in-plugin collector's timers (src/collector-service.js): unref'd, and
  // every callback is caught, so they never hold the host open or throw into it.
  try {
    toolkit.collector.start()
  } catch (error) {
    runtime.log?.warn?.("the collector could not start", error)
  }
  try {
    toolkit.plugins.start()
  } catch (error) {
    runtime.log?.warn?.("plugin discovery could not start", error)
  }
  // The job host's heartbeat is behind the collector's own switch: one switch
  // turns off everything Memory does in the background in this process.
  try {
    if (runtime.config.collect) toolkit.jobHost.start()
  } catch (error) {
    runtime.log?.warn?.("the job host could not start", error)
  }
  return {
    dispose: async () => {
      toolkit.wikiIngest?.stop?.()
      await toolkit.jobHost.stop()
      await toolkit.plugins.stop()
      await toolkit.collector.stop()
      await tools?.dispose?.()
      await command?.dispose?.()
    },
  }
}

/**
 * Register every tool on `editor`: the core tools, the documents tool, share,
 * spaces, the collector's ingest and cursor, collect, then the renamed shims.
 * A tool's description is registered as it is written: jelly's Code Mode shows
 * only its first 117 characters, so what goes there is in each tool's own
 * opening sentence (jelly #89 B4), never prefixed on from elsewhere.
 */
export function buildToolset(editor, toolkit, core = CORE_TOOLS) {
  for (const register of core) register(editor, toolkit)
  registerRead(editor, toolkit)
  registerCode(editor, toolkit)
  registerWiki(editor, toolkit)
  registerShare(editor, toolkit)
  registerSpaces(editor, toolkit)
  registerIngest(editor, toolkit)
  registerCollect(editor, toolkit)
  registerAliases(editor, toolkit)
}

/** True when a call can change memory: remember, or a tool's write action (WRITE_ACTIONS). */
export function isWriteCall(name, input) {
  if (name === "remember") return true
  return Boolean(WRITE_ACTIONS[name]?.includes(String(input?.action ?? "")))
}

/**
 * An editor whose added tools answer the unavailable sentence before running,
 * and whose core tools are pinned in Code Mode's catalogue (PINNED_TOOLS).
 */
function gateEditor(editor, runtime) {
  return new Proxy(editor, {
    get(target, key, receiver) {
      if (key !== "add") return Reflect.get(target, key, receiver)
      return (definition) =>
        target.add({
          ...definition,
          options: { ...definition.options, ...(PINNED_TOOLS.includes(definition.name) ? { pinned: true } : {}) },
          execute: (input, context) => {
            // With held team writes, every write runs as the verified speaker,
            // whatever its tool: a shared write is then held or asked by the
            // one gate (toolkit.gateWrite), never by a per-tool list here.
            const held = runtime.config.heldTeamWrites && isWriteCall(definition.name, input)
            const run = async () => {
              const reason = (runtime.availability ? await runtime.availability() : runtime.unavailable?.()) ?? ""
              if (reason) return { content: reason }
              // One tool call is one logical call: its records writes derive
              // their idempotency keys from its ids (docs/design/records-idempotency.md).
              return withWriteCall(context, definition.name, input, () => definition.execute(input, context))
            }
            return held ? asVerifiedSession(context?.sessionID, run) : asSession(context?.sessionID, run)
          },
        })
    },
  })
}

